 std::shared_ptr<const dt::IntervalValidatedProfileHandleV3> missing;facts=valid;facts.privacy_admitted=false;expect(missing,encoded,facts,normal,"OPTIMIZER.STATISTICS_PRIVACY_DENIED","statistics_privacy","statistics privacy precedes profile");
 facts=valid;expect(missing,std::span<const p::byte>{},facts,normal,"SBLR.OPERAND_INVALID","statistics_profile","statistics profile precedes structure");
 auto structure=encoded;structure[0]^=1;structure[368]^=1;expect(profile,structure,facts,normal,"CTI.TEMPORAL.CANONICAL_ENCODING_INVALID","statistics_structure","statistics structure precedes integrity");
 auto integrity=encoded;integrity[32]^=1;expect(profile,integrity,facts,normal,"SBLR.ENVELOPE.CHECKSUM_INVALID","statistics_integrity","statistics integrity precedes authority");
 auto authority=encoded;authority[32]^=1;ResealStatistics(authority);facts=valid;facts.source_object_uuid=Uuid(8);expect(profile,authority,facts,normal,"CTI.INTERVAL.DESCRIPTOR_INVALID","statistics_authority","statistics authority precedes source");
 facts=valid;facts.source_object_uuid=Uuid(8);facts.statistics_snapshot_uuid=Uuid(9);expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_source","statistics source precedes snapshot");
 facts=valid;facts.statistics_snapshot_uuid=Uuid(9);facts.schema_epoch=99;expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_snapshot","statistics snapshot precedes schema epoch");
 facts=valid;facts.schema_epoch=99;facts.collection_epoch=99;expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_schema_epoch","statistics schema precedes collection epoch");
 facts=valid;facts.collection_epoch=99;facts.security_epoch=99;expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_collection_epoch","statistics collection precedes security epoch");
 facts=valid;facts.security_epoch=99;facts.provider_evidence_uuid=Uuid(9);expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_security_epoch","statistics security epoch precedes provider");
 facts=valid;facts.provider_evidence_uuid=Uuid(9);facts.authenticated_population=false;expect(profile,encoded,facts,normal,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_provider","statistics provider precedes population");
 dt::IntervalExecutionControlV3 denied;denied.maximum_allocation_bytes=0;facts=valid;facts.authenticated_population=false;expect(profile,encoded,facts,denied,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_authenticated_population","statistics population precedes resource");
 facts=valid;facts.row_count=11;facts.value_count=9;expect(profile,encoded,facts,denied,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_counts","statistics exact counts precede resource");
 auto mismatched_mcv=std::vector<dt::IntervalStatisticsMcvRecordV3>(valid.mcv.begin(),valid.mcv.end());mismatched_mcv[0].frequency=7;facts=valid;facts.mcv=mismatched_mcv;expect(profile,encoded,facts,denied,"OPTIMIZER.STATISTICS_EPOCH_MISMATCH","statistics_mcv","statistics exact MCV precedes resource");
 auto noncanonical_counts=encoded;Put64(noncanonical_counts.data()+336,9);ResealStatistics(noncanonical_counts);expect(profile,noncanonical_counts,valid,normal,"CTI.TEMPORAL.CANONICAL_ENCODING_INVALID","statistics_counts","statistics intrinsic counts remain canonical invalid");
 auto noncanonical_mcv=encoded;Put64(noncanonical_mcv.data()+448+32,9);ResealStatistics(noncanonical_mcv);expect(profile,noncanonical_mcv,valid,normal,"CTI.TEMPORAL.CANONICAL_ENCODING_INVALID","statistics_mcv","statistics intrinsic MCV remains canonical invalid");
 denied.cancelled=Cancel;facts=valid;auto resource=expect(profile,encoded,facts,denied,"RESOURCE.BUDGET_EXCEEDED","statistics_allocation","statistics resource precedes cancellation");Check(resource.mcv_records_read==1,"statistics resource refusal records scanned");
